// epsilon-scaling auction for square minimization
int auction(const double *c, int n, int *out) {
 double *p=calloc(n,sizeof(double));
 int *owner=malloc(n*sizeof(int));
 int *next=malloc(n*sizeof(int));
 double maxc=0;
 for(int z=0;z<n*n;z++) if(c[z]>maxc) maxc=c[z];
 double eps=maxc/8.0;
 for(int j=0;j<n;j++) owner[j]=-1;
 long long total=0;
 while(eps > 1e-10) {
   for(int i=0;i<n;i++){out[i]=-1; next[i]=i+1;}
   next[n-1]=-1; int head=0;
   for(int j=0;j<n;j++)owner[j]=-1;
   long long lim=(long long)n*n*100;
   while(head>=0) {
     int i=head; head=next[i];
     const double *r=c+(long long)i*n;
     double v1=DBL_MAX,v2=DBL_MAX; int bj=-1;
     for(int j=0;j<n;j++) {double v=r[j]+p[j]; if(v<v1){v2=v1;v1=v;bj=j;} else if(v<v2)v2=v;}
     double bid=v2-v1+eps;
     p[bj]+=bid;
     int old=owner[bj]; owner[bj]=i; out[i]=bj;
     if(old>=0){out[old]=-1;next[old]=head;head=old;}
     if(++total>lim) {free(p);free(owner);free(next);return -1;}
   }
   eps/=8.0;
 }
 free(p);free(owner);free(next);return 0;
}
